1. @page "/dashboard"
2. @attribute [Authorize(Roles = "Dispatcher")]
3. @inject IShipmentService ShipmentService
4. 
5. <PageTitle>Dashboard</PageTitle>
6. 
7. <h1>Shipment Dashboard</h1>
8. 
9. <div class="row mb-3">
10.     <div class="col-md-4">
11.         <label class="form-label">Filter by Status</label>
12.         <select class="form-select" @bind="selectedStatus">
13.             <option value="">All</option>
14.             @foreach (var status in Enum.GetValues<ShipmentStatus>())
15.             {
16.                 <option value="@status">@status</option>
17.             }
18.         </select>
19.     </div>
20.     <div class="col-md-4">
21.         <label class="form-label">Search</label>
22.         <input type="text" class="form-control" placeholder="Tracking # or destination..." @bind="searchText" @bind:event="oninput" />
23.     </div>
24. </div>
25. 
26. @if (shipments is null)
27. {
28.     <p><em>Loading shipments...</em></p>
29. }
30. else
31. {
32.     <div class="table-responsive">
33.         <table class="table table-striped table-hover">
34.             <thead>
35.                 <tr>
36.                     <th>Tracking #</th>
37.                     <th>Origin</th>
38.                     <th>Destination</th>
39.                     <th>Status</th>
40.                     <th>Shipped Date</th>
41.                     <th>Est. Delivery</th>
42.                     <th>Update Status</th>
43.                 </tr>
44.             </thead>
45.             <tbody>
46.                 @foreach (var shipment in FilteredShipments)
47.                 {
48.                     <tr>
49.                         <td>@shipment.TrackingNumber</td>
50.                         <td>@shipment.Origin</td>
51.                         <td>@shipment.Destination</td>
52.                         <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
53.                         <td>@shipment.ShippedDate.ToString("yyyy-MM-dd")</td>
54.                         <td>@shipment.EstimatedDelivery.ToString("yyyy-MM-dd")</td>
55.                         <td>
56.                             <div class="d-flex gap-1">
57.                                 <select class="form-select form-select-sm" style="width: auto;" @bind="statusUpdates[shipment.Id]">
58.                                     @foreach (var status in Enum.GetValues<ShipmentStatus>())
59.                                     {
60.                                         <option value="@status">@status</option>
61.                                     }
62.                                 </select>
63.                                 <button class="btn btn-sm btn-primary" @onclick="() => SaveStatus(shipment)">Save</button>
64.                             </div>
65.                         </td>
66.                     </tr>
67.                 }
68.             </tbody>
69.         </table>
70.     </div>
71. }
72. 
73. @if (!string.IsNullOrEmpty(message))
74. {
75.     <div class="alert alert-info mt-2">@message</div>
76. }
77. 
78. @code {
79.     private List<Shipment>? shipments;
80.     private string selectedStatus = "";
81.     private string searchText = "";
82.     private string? message;
83.     private Dictionary<int, ShipmentStatus> statusUpdates = new();
84. 
85.     private IEnumerable<Shipment> FilteredShipments
86.     {
87.         get
88.         {
89.             if (shipments is null) return [];
90. 
91.             var filtered = shipments.AsEnumerable();
92. 
93.             if (!string.IsNullOrEmpty(selectedStatus) && Enum.TryParse<ShipmentStatus>(selectedStatus, out var status))
94.             {
95.                 filtered = filtered.Where(s => s.Status == status);
96.             }
97. 
98.             if (!string.IsNullOrWhiteSpace(searchText))
99.             {
100.                 var term = searchText.Trim();
101.                 filtered = filtered.Where(s =>
102.                     s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
103.                     s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase));
104.             }
105. 
106.             return filtered;
107.         }
108.     }
109. 
110.     protected override async Task OnInitializedAsync()
111.     {
112.         await LoadShipments();
113.     }
114. 
115.     private async Task LoadShipments()
116.     {
117.         shipments = await ShipmentService.GetAllShipmentsAsync();
118.         statusUpdates = shipments.ToDictionary(s => s.Id, s => s.Status);
119.     }
120. 
121.     private async Task SaveStatus(Shipment shipment)
122.     {
123.         if (statusUpdates.TryGetValue(shipment.Id, out var newStatus) && newStatus != shipment.Status)
124.         {
125.             await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
126.             message = $"Status for {shipment.TrackingNumber} updated to {newStatus}.";
127.             await LoadShipments();
128.         }
129.     }
130. 
131.     private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
132.     {
133.         ShipmentStatus.Pending => "bg-secondary",
134.         ShipmentStatus.PickedUp => "bg-info text-dark",
135.         ShipmentStatus.InTransit => "bg-primary",
136.         ShipmentStatus.OutForDelivery => "bg-warning text-dark",
137.         ShipmentStatus.Delivered => "bg-success",
138.         ShipmentStatus.Delayed => "bg-danger",
139.         _ => "bg-secondary"
140.     };
141. }
142.

