 @page "/track"
 @attribute [Authorize]
 @inject IShipmentService ShipmentService
 @inject AuthenticationStateProvider AuthStateProvider

 <PageTitle>Track Shipment</PageTitle>

 <h1>Track a Shipment</h1>

 <div class="row mb-4">
     <div class="col-md-6">
         <div class="input-group">
             <input type="text" class="form-control" placeholder="Enter tracking number (e.g. ST-100001)" @bind="trackingNumber" @onkeydown="HandleKeyDown" />
             <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
         </div>
     </div>
 </div>

 @if (!string.IsNullOrEmpty(errorMessage))
 {
     <div class="alert alert-warning">@errorMessage</div>
 }

 @if (trackedShipment is not null)
 {
     <div class="card mb-4" style="max-width: 600px;">
         <div class="card-header">
             <strong>@trackedShipment.TrackingNumber</strong>
             <span class="badge @GetStatusBadgeClass(trackedShipment.Status) ms-2">@trackedShipment.Status</span>
         </div>
